// 书源版 _httpPost：Rhino 直接 java 互操作，兼容任意 Legado 版本
function _httpPost(url,body,headers){
  try{
    var u=new Packages.java.net.URL(url);
    var conn=u.openConnection();
    conn.setRequestMethod('POST');
    conn.setDoOutput(true);
    conn.setConnectTimeout(8000);
    conn.setReadTimeout(8000);
    for(var k in headers)conn.setRequestProperty(k,headers[k]);
    var os=conn.getOutputStream();
    var bytes=new Packages.java.lang.String(body).getBytes('UTF-8');
    os.write(bytes,0,bytes.length);
    os.flush();os.close();
    var code=conn.getResponseCode();
    var is=(code>=200&&code<300)?conn.getInputStream():conn.getErrorStream();
    var br=new Packages.java.io.BufferedReader(new Packages.java.io.InputStreamReader(is,'UTF-8'));
    var sb=new Packages.java.lang.StringBuilder();var line;
    while((line=br.readLine())!==null)sb.append(line);
    br.close();
    return String(sb.toString());
  }catch(e){return '';}
}
